INSERT INTO public.catechism_official (paragraph, content) VALUES (1, 'Deus, infinitamente perfeito e bem-aventurado em Si mesmo, num desígnio de pura bondade, criou livremente o homem para o tornar participante da sua vida bem-aventurada. Por isso, sempre e em toda a parte, Ele está próximo do homem. Chama-o e ajuda-o a procurá-Lo, a conhecê-Lo e a amá-Lo com todas as suas forças. Convoca todos os homens, dispersos pelo pecado, para a unidade da sua família que é a Igreja. Para tal, enviou o seu Filho como Redentor e Salvador na plenitude dos tempos. N''Ele e por Ele, chama os homens a tornarem-se, no Espírito Santo, seus filhos adoptivos e, portanto, herdeiros da sua vida bem-aventurada.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (2, 'Para que este convite se fizesse ouvir por toda a Terra, Cristo enviou os Apóstolos que escolhera, dando-lhes o mandato de anunciar o Evangelho: «Ide, pois, fazei discípulos de todas as nações, baptizando-os em nome do Pai e do Filho e do Espírito Santo, ensinando-os a cumprirem tudo quanto vos prescrevi. E eis que Eu estou convosco todos os dias até ao fim do mundo» (Mt 28, 19-20). Fortalecidos por esta missão, os Apóstolos «partiram a pregar por toda a parte e o Senhor cooperava com eles confirmando a Palavra com os sinais que a acom­panhavam» (Mc 16, 20).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (3, 'Aqueles que, com a ajuda de Deus, aceitaram o convite de Cristo e livremente Lhe responderam, foram por sua vez impelidos, pelo amor do mesmo Cristo, a anunciar por toda a parte a Boa-Nova. Este tesouro, recebido dos Apóstolos, foi fielmente guardado pelos seus sucessores. Todos os fiéis de Cristo são chamados a transmiti-lo de geração em geração, anunciando a fé, vivendo-a em partilha fraterna e celebrando-a na liturgia e na oração (1).
INSERT INTO public.catechism_official (paragraph, content) VALUES (4, 'Bem cedo se chamou catequese ao conjunto de esforços empreendidos na Igreja para fazer discípulos, para ajudar os homens a acreditar que Jesus é o Filho de Deus, a fim de, pela fé, terem a vida em seu nome, e para os educar e instruir nessa vida, construindo assim o Corpo de Cristo (2).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (5, '«A catequese é uma educação da fé das crianças, dos jovens e dos adultos, que compreende especialmente o ensino da doutrina cristã, ministrado em geral dum modo orgânico e sistemático, em ordem à iniciação na plenitude da vida cristã» (3).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (6, 'Sem se confundir com eles, a catequese articula-se com um certo número de elementos da missão pastoral da Igreja que têm um aspecto catequético, preparam para a catequese ou dela derivam: o primeiro anúncio do Evangelho ou pregação missionária, para suscitar a fé; a busca das razões de acreditar; a experiência da vida cristã; a celebração dos sacramentos; a integração na comunidade eclesial; o testemunho apostólico e missionário (4)') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (7, '«A catequese está intimamente ligada a toda a vida da Igreja. Dependem essencialmente dela não só a expansão geográfica e o crescimento numérico, mas também, e muito mais ainda, o crescimento interior da Igreja e a sua conformidade com o desígnio de Deus» (5).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (8, 'Os períodos de renovação da Igreja são também tempos fortes de catequese. Assim, na grande época dos Padres da Igreja, vemos santos bispos consagrarem parte importante do seu ministério à catequese, como por exemplo São Cirilo de Jerusalém, São João Crisóstomo, Santo Ambrósio, Santo Agostinho e tantos outros Padres, cujas obras catequéticas continuam a ser modelo.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (9, 'O ministério da catequese vai buscar energias sempre novas aos concílios. O Concílio de Trento constitui, a este respeito, um exemplo a sublinhar: nas suas constituições e decretos, deu prioridade à catequese; está na origem do Catecismo Romano que tem o seu nome e que constitui um trabalho de primeira ordem como compêndio da doutrina cristã; fez nascer na Igreja uma organização notável da catequese; e, graças a santos bispos e teólogos, como São Pedro Canísio, São Carlos Borromeo, São Toríbio de Mogrovejo e São Roberto Belarmino, levou à publicação de numerosos catecismos.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (10, 'Não admira, pois, que, na sequência do II Concílio do Vaticano (que o Papa Paulo VI considerava como o grande catecismo dos tempos modernos), a catequese da Igreja tenha de novo chamado a atenção. O Directório catequético geral, de 1971; as sessões do Sínodo dos Bispos consagradas à evangelização (1974) e à catequese (1977): e as exortações apostólicas correspondentes — Evangelii nuntiandi (1975) e Catechesi tradendae (1979) — são disso bom testemunho. A assembleia extraordinária do Sínodo dos Bispos de 1985 pediu: «que seja redigido um catecismo ou compêndio de toda a doutrina católica, tanto no tocante à fé como no que respeita à moral» (6). O Santo Padre João Paulo II fez seu este voto do Sínodo dos Bispos. Reconheceu que «tal desejo corresponde inteiramente a uma verdadeira necessidade da Igreja universal e das Igrejas particulares»(7). E pôs todo o seu empenho cm que se concretizasse este desejo dos Padres sinodais.
INSERT INTO public.catechism_official (paragraph, content) VALUES (11, 'A finalidade deste Catecismo é apresentar uma exposição orgânica e sintética dos conteúdos essenciais e fundamentais da doutrina católica, tanto sobre a fé como sobre a moral, à luz do II Concilio do Vaticano e do conjunto da Tradição da Igreja. As suas fontes principais são a Sagrada Escritura, os santos Padres, a liturgia e o Magistério da Igreja. E destina-se a servir «como ponto de referência aos catecismos ou compêndios a publicar nos diversos países» (8).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (12, 'Este Catecismo destina-se principalmente aos responsáveis pela catequese, que são em primeiro lugar os bispos, enquanto doutores da fé e pastores da Igreja. É-lhes oferecido como instrumento para o desempenho da sua missão de ensinar o povo de Deus. E, através dos bispos, dirige-se aos redactores de catecismos, aos sacerdotes e aos catequistas. Será também uma leitura útil para todos os outros fiéis cristãos.
INSERT INTO public.catechism_official (paragraph, content) VALUES (13, 'O plano deste Catecismo inspira-se na grande tradição dos catecismos que articulam a catequese cm torno de quatro «pilares»: a profissão da fé baptismal (Símbolo), os sacramentos da fé, a vida da fé (Mandamentos) e  a oração do crente (o Pai Nosso).
INSERT INTO public.catechism_official (paragraph, content) VALUES (14, 'Aqueles que, pela fé e pelo Baptismo, pertencem a Cristo, devem confessar a sua fé baptismal diante dos homens (9). Por isso, o Catecismo começa por expor em que consiste a Revelação, pela qual Deus Se dirige e Se dá ao homem, e a fé pela qual o homem responde a Deus (Primeira Secção). O Símbolo da fé resume os dons que Deus faz ao homem, como Autor de todo o bem, Redentor e Santificador, e articula-os em volta dos «três capítulos» do nosso Baptismo – a fé num só Deus: o Pai Todo-poderoso, Criador; e o seu Filho Jesus Cristo, nosso Senhor e Salvador: e o Espírito Santo, na Santa Igreja (Segunda Secção).
INSERT INTO public.catechism_official (paragraph, content) VALUES (15, 'A segunda parte do Catecismo expõe como a salvação de Deus, realizada uma vez por todas por Jesus Cristo e pelo Espírito Santo, se toma presente nas acções sagradas da liturgia da Igreja(Primeira Secção), e em especial nos sete sacramentos (Segunda Secção).
INSERT INTO public.catechism_official (paragraph, content) VALUES (16, 'A terceira parte do Catecismo apresenta o fim último do homem, criado à imagem de Deus – a bem-aventurança e os caminhos para a ela chegar: um comportamento recto e livre, com a ajuda da lei de Deus e da sua graça (Primeira Secção); um comportamento que realize o duplo mandamento da caridade, explicitado nos dez Mandamentos de Deus (Segunda Secção).
INSERT INTO public.catechism_official (paragraph, content) VALUES (18, 'Este Catecismo foi concebido como uma exposição orgânica de toda a fé católica. Deve, portanto, ser lido como um todo. Numerosas notas remissivas à margem do texto (números impressos em tipos menores remetendo para outros parágrafos que tratam do mesmo assunto) e o índice analítico no fim do volume, permitem encarar cada tema na sua ligação com o conjunto da fé.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (19, 'Muitas vezes, os textos da Sagrada Escritura não são citados literalmente, mas com a simples indicação da referência (por meio dum cf.) feita em nota. Para uma inteligência aprofundada desses passos, convém recorrer aos próprios textos. Tais referências bíblicas são um instrumento de trabalho para a catequese.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (20, 'Quando, cm certas passagens, se emprega a letra miúda, isso quer dizer que se trata de anotações de tipo histórico ou apologético, ou de exposições doutrinais complementares.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (21, 'As citações, em letra miúda, de fontes patrísticas, litúrgicas, do Magistério ou da hagiografia, destinam-se a enriquecer a exposição doutrinal. Frequentemente, esses textos foram escolhidos a pensar num emprego directamente catequético.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (22, 'No fim de cada unidade temática, uma série de textos breves resume, em fórmulas escolhidas, o essencial do ensinamento. Estes «RESUMINDO» têm por fim dar à catequese local sugestões de fórmulas sintéticas e fáceis de decorar.
INSERT INTO public.catechism_official (paragraph, content) VALUES (23, 'A tónica deste Catecismo incide sobre a exposição doutrinal. Com efeito, a sua intenção é ajudar a aprofundar o conhecimento da fé. Todo ele se orienta no sentido do amadurecimento da mesma fé, do seu enraizamento na vida e da sua irradiação no testemunho (10).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (24, 'Pela sua própria finalidade, este Catecismo não se propõe realizar as adaptações da exposição e dos métodos catequéticos, exigidas pelas diferenças de culturas, idades, maturidade espiritual, situações sociais e eclesiais daqueles a quem a catequese se dirige. Essas indispensáveis adaptações pertencem aos catecismos apropriados e, sobretudo, àqueles que ministram o ensino aos fiéis:
INSERT INTO public.catechism_official (paragraph, content) VALUES (25, 'A concluir esta apresentação, é oportuno Lembrar este princípio pastoral enunciado pelo Catecismo Romano:
INSERT INTO public.catechism_official (paragraph, content) VALUES (26, 'Quando professamos a nossa fé, começamos por dizer: «Creio», ou «Cremos». Portanto, antes de expor a fé da Igreja, tal como é confessada no Credo, celebrada na liturgia, vivida na prática dos mandamentos e na oração, perguntemos a nós mesmos o que significa «crer». A fé é a resposta do homem a Deus, que a ele Se revela e Se oferece, resposta que, ao mesmo tempo, traz uma luz superabundante ao homem que busca o sentido último da sua vida. Comecemos, pois, por considerar esta busca do homem (capítulo primeiro): depois, a Revelação divina pela qual Deus vem ao encontro do homem (capítulo segundo); finalmente, a resposta da fé (capítulo terceiro).
INSERT INTO public.catechism_official (paragraph, content) VALUES (27, 'O desejo de Deus é um sentimento inscrito no coração do homem, porque o homem foi criado por Deus e para Deus. Deus não cessa de atrair o homem para Si e só em Deus é que o homem encontra a verdade e a felicidade que procura sem descanso:
INSERT INTO public.catechism_official (paragraph, content) VALUES (28, 'De muitos modos, na sua história e até hoje, os homens exprimiram a sua busca de Deus em crenças e comportamentos religiosos (orações, sacrifícios, cultos, meditações, etc.). Apesar das ambiguidades de que podem enfermar, estas formas de expressão são tão universais que bem podemos chamar ao homem um ser religioso:
INSERT INTO public.catechism_official (paragraph, content) VALUES (29, 'Mas esta «relação íntima e vital que une o homem a Deus»(2) pode ser esquecida, desconhecida e até explicitamente rejeitada pelo homem. Tais atitudes podem ter origens diversas (3) a revolta contra o mal existente no mundo, a ignorância ou a indiferença religiosas, as preocupações do mundo e das riquezas(4), o mau exemplo dos crentes, as correntes de pensamento hostis à religião e, finalmente, a atitude do homem pecador que, por medo, se esconde de Deus(5) e foge quando Ele o chama (6).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (30, '«Exulte o coração dos que procuram o Senhor» (Sl 105, 3). Se o homem pode esquecer ou rejeitar Deus, Deus é que nunca deixa de chamar todo o homem a que O procure, para que encontre a vida e a felicidade. Mas esta busca exige do homem todo o esforço da sua inteligência, a rectidão da sua vontade, «um coração recto», e também o testemunho de outros que o ensinam a procurar Deus.
INSERT INTO public.catechism_official (paragraph, content) VALUES (31, 'Criado à imagem de Deus, chamado a conhecer e a amar a Deus, c homem que procura Deus descobre certos «caminhos» de acesso ao conhecimento de Deus. Também se lhes chama «provas da existência de Deus» – não no sentido das provas que as ciências naturais indagam mas no de «argumentos convergentes e convincentes» que permitem chegar a verdadeiras certezas.
INSERT INTO public.catechism_official (paragraph, content) VALUES (32, 'O mundo: A partir do movimento e do devir, da contingência, da ordem e da beleza do mundo, pode chegar-se ao conhecimento de Deu: como origem e fim do universo.
INSERT INTO public.catechism_official (paragraph, content) VALUES (33, 'O homem: Com a sua abertura à verdade e à beleza, com o seu sentido do bem moral, com a sua liberdade e a voz da sua consciência, com a sua ânsia de infinito e de felicidade, o homem interroga-se sobre a existência de Deus. Nestas aberturas, ele detecta sinais da sua alma espiritual. «Gérmen de eternidade que traz em si mesmo, irredutível à simples matéria» (10), a sua alma só em Deus pode ter origem.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (34, 'O mundo e o homem atestam que não têm em si mesmos, nem o seu primeiro princípio, nem o seu fim último, mas que participam do Ser-em-si, sem princípio nem fim. Assim, por estes diversos «caminhos», o homem pode ter acesso ao conhecimento da existência duma realidade que é a causa primeira e o fim último de tudo, «e a que todos chamam Deus» (11).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (35, 'As faculdades do homem tornam-no capaz de conhecer a existência de um Deus pessoal. Mas, para que o homem possa entrar na sua intimidade, Deus quis revelar-Se ao homem e dar-lhe a graça de poder receber com fé esta revelação. Todavia, as provas da existência de Deus podem dispor para a fé e ajudar a perceber que a fé não se opõe à razão humana.
INSERT INTO public.catechism_official (paragraph, content) VALUES (36, '«A Santa Igreja, nossa Mãe, atesta e ensina que Deus, princípio e fim de todas as coisas, pode ser conhecido, com certeza, pela luz natural da razão humana, a partir das coisas criadas» (12). Sem esta capacidade, o homem não poderia acolher a revelação de Deus. O homem tem esta capacidade porque foi criado «à imagem de Deus» (Gn 1, 27).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (37, 'Nas condições históricas em que se encontra, o homem experimenta, no entanto, muitas dificuldades para chegar ao conhecimento de Deus só com as luzes da razão:
INSERT INTO public.catechism_official (paragraph, content) VALUES (38, 'É por isso que o homem tem necessidade de ser esclarecido pela Revelação de Deus, não somente no que diz respeito ao que excede o seu entendimento, mas também sobre «as verdades religiosas e morais que, de si, não são inacessíveis à razão, para que possam ser, no estado actual do género humano, conhecidas por todos sem dificuldade, com uma certeza firme e sem mistura de erro» (14).
INSERT INTO public.catechism_official (paragraph, content) VALUES (39, 'Ao defender a capacidade da razão humana para conhecer Deus, a Igreja exprime a sua confiança na possibilidade de falar de Deus a todos os homens e com todos os homens. Esta convicção está na base do seu diálogo com as outras religiões, com a filosofia e as ciências, e também com os descrentes e os ateus.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (40, 'Mas dado que o nosso conhecimento de Deus é limitado, a nossa linguagem, ao falar de Deus, também o é. Não podemos falar de Deus senão a partir das criaturas e segundo o nosso modo humano limitado de conhecer e de pensar.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (41, 'Todas as criaturas são portadoras duma certa semelhança de Deus, muito especialmente o homem, criado à imagem e semelhança de Deus. As múltiplas perfeições das criaturas (a sua verdade, a sua bondade, a sua beleza) reflectem, pois, a perfeição infinita de Deus. Daí que possamos falar de Deus a partir das perfeições das suas criaturas: «porque a grandeza e a beleza das criaturas conduzem, por analogia, à contemplação do seu Autor» (Sb 13, 5).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (42, 'Deus transcende toda a criatura. Devemos, portanto, purificar incessantemente a nossa linguagem no que ela tem de limitado, de ilusório, de imperfeito, para não confundir o Deus «inefável, incompreensível, invisível, impalpável» (15) com as nossas representações humanas. As nossas palavras humanas ficam sempre aquém do mistério de Deus.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (43, 'Ao falar assim de Deus, a nossa linguagem exprime-se, evidentemente, de modo humano. Mas atinge realmente o próprio Deus, sem todavia poder exprimi-Lo na sua infinita simplicidade. Devemos lembrar-nos de que, «entre o Criador e a criatura, não é possível notar uma semelhança sem que a dissemelhança seja ainda maior» (16), e de que «não nos é possível apreender de Deus o que Ele é, senão apenas o que Ele não é, e como se situam os outros seres em relação a Ele»(17).
INSERT INTO public.catechism_official (paragraph, content) VALUES (44, 'O homem é, por natureza e vocação, um ser religioso. Vindo de Deus e caminhando para Deus, o homem não vive uma vida plenamente humana senão na medida em que livremente viver a sua relação com Deus.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (45, 'O homem foi feito para viver em comunhão com Deus, em quem encontra a sua felicidade: «Quando eu estiver todo em Ti, não mais haverá tristeza nem angústia; inteiramente repleta de Ti, a minha vida será vida plena»(18).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (46, 'Quando escuta a mensagem das criaturas e a voz da sua consciência, o homem pode alcançar a certeza da existência de Deus, causa e fim de tudo.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (47, 'A Igreja ensina que o Deus único e verdadeiro, nosso Criador e Senhor; pode ser conhecido com certeza pelas suas obras, graças à luz natural da razão humana  (19).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (48, 'Nós podemos realmente falar de Deus partindo das múltiplas perfeições das criaturas, semelhanças de Deus infinitamente perfeito, ainda que a nossa linguagem limitada não consiga esgotar o mistério.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (49, '«A criatura sem o Criador esvai-se» (20). Por isso, os crentes sentem-se pressionados pelo amor de Cristo a levar a luz do Deus vivo aos que O ignoram ou rejeitam.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (50, 'II Concílio do Vaticano, Const. dogm. Dei Verbum, 10: AAS 58 (1966) 822.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (51, 'II Concílio do Vaticano, Const. dogm. Dei Verbum, 10: AAS 58 (1966) 822.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (52, 'II Concílio do Vaticano. Const. dogm. Dei Verbum, 10: AAS 58 (1966) 822.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (53, 'Cf. II Concílio do Vaticano, Const. dogm. Lumen Gentium, 20: AAS 57 (1965) 24.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (54, 'Cf. Jo 8, 31-32.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (55, 'Cf. I Concílio do Vaticano, Const. dogm. Dei Filius,  c. 4: DS 3016 «mysteriorum nexus». Cf. II Concílio do Vaticano, Const. dogm. Lumen Gentium, 25: AAS 57 (1965) 29.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (56, 'II Concílio do Vaticano, Decr. Unitatis redintegratio, 11: AAS 57 (1965) 99.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (57, 'Cf. 1 Jo 2, 20. 27.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (58, 'II Concílio do Vaticano, Const. dogm. Lumen Gentium, 12: AAS 57 (1965) 16.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (59, 'II Concílio do Vaticano. Const. dogm. Lumen Gentium, 12: AAS 57 (1965) 16.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (60, 'II Concílio do Vaticano, Const. dogm. Dei Verbum, 8: AAS 58 (1966) 821.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (61, 'II Concílio do Vaticano, Const. past. Gaudium et spes, 62: AAS 58 (1966) 1084: cf. Ibid.. 44: AAS 58 (1966) 1065; Const. dogm. Dei Verbum, 23: AAS 58 (1966) 828; Ibid. 24: AAS 58 (1966) 828-829: Decr. Unitatis redintegratio, 4: AAS 57 (1965) 94.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
