INSERT INTO public.catechism_official (paragraph, content) VALUES (118, 'Cf. Orígenes, Homiliae in Exodum 4, 5: SC 321, 128 (PG 12, 320).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (119, 'II Concílio do Vaticano, Const. dogm. Dei Verbum, 21: AAS 58 (1966) 827.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (120, 'Cf. Is 50, 4.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (121, 'O Antigo Testamento é uma parte da Sagrada Escritura de que não se pode prescindir. Os seus livros são divinamente inspirados e conservam um valor permanente (99), porque a Antiga Aliança nunca foi revogada.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (122, 'Efectivamente, «a "economia"do Antigo Testamento destinava-se, sobretudo, a preparar [...] o advento de Cristo, redentor universal».
INSERT INTO public.catechism_official (paragraph, content) VALUES (123, 'Os cristãos veneram o Antigo Testamento como verdadeira Palavra de Deus. A Igreja combateu sempre vigorosamente a ideia de rejeitar o Antigo Testamento, sob o pretexto de que o Novo o teria feito caducar (Marcionismo).
INSERT INTO public.catechism_official (paragraph, content) VALUES (124, '«A Palavra de Deus, que é força de Deus para salvação de quem acredita, apresenta-se e manifesta o seu poder dum modo eminente nos escritos do Novo Testamento»(101). Estes escritos transmitem-nos a verdade definitiva da Revelação divina. O seu objecto central é Jesus Cristo, o Filho de Deus encarnado, os seus actos, os seus ensinamentos, a sua Paixão e glorificação, bem como os primórdios da sua Igreja sob a acção do Espírito Santo (102).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (125, 'Os evangelhos são o coração de todas as Escrituras, «enquanto são o principal testemunho da vida e da doutrina do Verbo encarnado, nosso Salvador» (103).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (126, 'Na formação dos evangelhos podemos distinguir três etapas:') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (127, 'O Evangelho quadriforme ocupa na Igreja um lugar único, de que são testemunhas a veneração de que a Liturgia o rodeia e o atractivo incomparável que em todos os tempos exerceu sobre os santos:
INSERT INTO public.catechism_official (paragraph, content) VALUES (128, 'A Igreja, já nos tempos apostólicos (107), e depois constantemente na sua Tradição, pôs em evidência a unidade, do plano divino nos dois Testamentos, graças à tipologia. Esta descobre nas obras de Deus, na Antiga Aliança, prefigurações do que o mesmo Deus realizou na plenitude dos tempos, na pessoa do seu Filho encarnado.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (129, 'Os cristãos lêem, pois, o Antigo Testamento à luz de Cristo morto e ressuscitado. Esta leitura tipológica manifesta o conteúdo inesgotável do Antigo Testamento. Mas não deve fazer-nos esquecer de que ele mantém o seu valor próprio de Revelação, reafirmado pelo próprio Jesus, nosso Senhor (108). Aliás, também o Novo Testamento requer ser lido à luz do Antigo. A catequese cristã primitiva recorreu constantemente a este método (109). Segundo um velho adágio, o Novo Testamento está oculto no Antigo, enquanto o Antigo é desvendado no Novo: « Novum in Vetere latet et in Novo Vetus patet» – «O Novo está oculto no Antigo, e o Antigo está patente no Novo» (110).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (130, 'A tipologia significa o dinamismo em ordem ao cumprimento do plano divino, quando «Deus for tudo em todos» (1 Cor 15, 28). Assim, a vocação dos patriarcas e o êxodo do Egipto, por exemplo, não perdem o seu valor próprio no plano de Deus pelo facto de, ao mesmo tempo, serem etapas intermédias desse mesmo plano.
INSERT INTO public.catechism_official (paragraph, content) VALUES (131, '«É tão grande a força e a virtude da Palavra de Deus, que ela se torna para a Igreja apoio e vigor e, para os filhos da Igreja, solidez da fé, alimento da alma, fonte pura e perene de vida espiritual» (111). É necessário que «os fiéis tenham largo acesso à Sagrada Escritura» (112).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (132, '«O estudo das Páginas sagradas deve ser como que a "alma" da sagrada teologia. Também o ministério da Palavra, isto é, a pregação pastoral, a catequese, e toda a espécie de instrução cristã, na qual a homilia litúrgica deve ter um lugar principal, com proveito se alimenta e santamente se revigora com a palavra da Escritura» (113).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (133, 'A Igreja «exorta com ardor e insistência todos os fiéis [...] a que aprendam "a sublime ciência de Jesus Cristo" (Fl. 3, 8) na leitura frequente da Sagrada Escritura. Porque "a ignorância das Escrituras é ignorância de Cristo"» (114).
INSERT INTO public.catechism_official (paragraph, content) VALUES (134, 'Omnis Scriptura divina unus liber est, et ille unus liber Christus est, «quia omnis Scriptura divina de Christo loquitur; et omnis Scriptura divina in Christo impletur» – Toda a Escritura divina é um só livro, e esse livro único é Cristo, «porque toda a Escritura divina fala de Cristo e toda a Escritura divina se cumpre em Cristo» (115).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (135, '«As Sagradas Escrituras contêm a Palavra de Deus; e, pelo facto de serem inspiradas, são verdadeiramente a Palavra de Deus» (116).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (136, 'Deus é o autor da Sagrada Escritura, ao inspirar os seus autores humanos: age neles e por eles. E assim nos dá a garantia de que os seus escritos ensinam, sem erro, a verdade da salvação (117).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (137, 'A interpretação das Escrituras inspiradas deve, antes de mais nada, estar atenta ao que Deus quer revelar, por meio dos autores sagrados, para nossa salvação. O que vem do Espírito não é plenamente entendido senão pela acção do Espírito (118).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (138, 'A Igreja recebe e venera, como inspirados, os 46 livros do Antigo e os 27 do Novo Testamento.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (139, 'Os quatro evangelhos ocupam um lugar central, dado que Jesus Cristo é o seu centro.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (140, 'A unidade dos dois Testamentos deriva da unidade do plano de Deus e da sua Revelação. O Antigo Testamento prepara o Novo, ao passo que o Novo dá cumprimento ao Antigo. Os dois esclarecem-se mutuamente; ambos são verdadeira Palavra de Deus.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (141, '«A Igreja sempre venerou as Divinas Escrituras, tal como o próprio Corpo do Senhor» (119) ambos alimentam e regem toda a vida cristã. «A vossa Palavra é farol para os meus passos e luz para os meus caminhos» (Sl 119, 105)(120).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (142, 'Pela sua revelação,  «Deus invisível, na riqueza do seu amor, fala aos homens como amigos e convive com eles, para os convidar e admitir à comunhão com Ele» (1). A resposta adequada a este convite é a fé.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (143, 'Pela fé,  o homem submete completamente a Deus a inteligência e a vontade; com todo o seu ser, o homem dá assentimento a Deus revelador (2). A Sagrada Escritura chama «obediência da fé» a esta resposta do homem a Deus revelador (3).
INSERT INTO public.catechism_official (paragraph, content) VALUES (144, 'Obedecer  (ob-audire)  na fé é submeter-se livremente à palavra escutada, por a sua verdade ser garantida por Deus, que é a própria verdade. Desta obediência, o modelo que a Sagrada Escritura nos propõe é Abraão. A sua realização mais perfeita é a da Virgem Maria.
INSERT INTO public.catechism_official (paragraph, content) VALUES (145, 'A Epístola aos Hebreus, no grande elogio que faz da fé dos antepassados, insiste particularmente na fé de Abraão: «Pela fé, Abraão  obedeceu  ao chamamento de Deus, e partiu para uma terra que viria a receber como herança: partiu, sem saber para onde ia»  (Heb 11, 8) (4). Pela fé, viveu como estrangeiro e peregrino na terra prometida (5). Pela fé, Sara recebeu a graça de conceber o filho da promessa. Pela fé, finalmente, Abraão ofereceu em sacrifício o seu filho único (6).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (146, 'Abraão realiza assim a definição da fé dada pela Epístola aos Hebreus: «A fé constitui a garantia dos bens que se esperam, e a prova de que existem as coisas que não se vêem» (Heb 11, 1). «Abraão acreditou em Deus, e isto foi-lhe atribuído como justiça» (Rm 4, 3) (7). «Fortalecido» por esta fé (Rm 4, 20), Abraão tornou-se «o pai de todos os crentes» (Rm 4, 11. 18) (8).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (147, 'O Antigo Testamento é rico em testemunhos desta fé. A Epístola aos Hebreus faz o elogio da fé exemplar dos antigos, «que lhes valeu um bom testemunho» (Heb 11, 2. 39). No entanto, para nós, «Deus previra destino melhor»: a graça de crer no seu Filho Jesus, «guia da nossa fé, que Ele leva à perfeição» (Heb 11, 40; 12, 2).
INSERT INTO public.catechism_official (paragraph, content) VALUES (148, 'A Virgem Maria realiza, do modo mais perfeito, a «obediência da fé». Na fé, Maria acolheu o anúncio e a promessa trazidos pelo anjo Gabriel, acreditando que «a Deus nada é impossível» (Lc 1, 37) (9) e dando o seu assentimento: «Eis a serva do Senhor, faça-se em mim segundo a tua palavra» (Lc 1, 38). Isabel saudou-a: «Feliz aquela que acreditou no cumprimento de quanto lhe foi dito da parte do Senhor» (Lc 1, 45). É em virtude desta fé que todas as gerações a hão-de proclamar bem-aventurada (10).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (149, 'Durante toda a sua vida e até à última provação (11), quando Jesus, seu filho, morreu na cruz, a sua fé jamais vacilou. Maria nunca deixou de crer «no cumprimento» da Palavra de Deus. Por isso, a Igreja venera em Maria a mais pura realização da fé.
INSERT INTO public.catechism_official (paragraph, content) VALUES (150, 'Antes de mais, a fé é uma adesão pessoal do homem a Deus. Ao mesmo tempo, e inseparavelmente, é o assentimento livre a toda a verdade revelada por Deus. Enquanto adesão pessoal a Deus e assentimento à verdade por Ele revelada, a fé cristã difere da fé numa pessoa humana. É justo e bom confiar totalmente em Deus e crer absolutamente no que Ele diz. Seria vão e falso ter semelhante fé numa criatura (12).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (151, 'Para o cristão, crer em Deus é crer inseparavelmente n''Aquele que Deus enviou – «no seu Filho muito amado» em quem Ele pôs todas as suas complacências (13): Deus mandou-nos que O escutássemos (14). O próprio Senhor disse aos seus discípulos: «Acreditais em Deus, acreditai também em Mim»  (Jo  14, 1). Podemos crer em Jesus Cristo, porque Ele próprio é Deus, o Verbo feito carne: «A Deus, nunca ninguém O viu. O Filho Unigénito, que está no seio do Pai, é que O deu a conhecer»  (Jo  1, 18). Porque «viu o Pai» (Jo 6, 46), Ele é o único que O conhece e O pode revelar (15).
INSERT INTO public.catechism_official (paragraph, content) VALUES (152, 'Não é possível acreditar em Jesus Cristo sem ter parte no seu Espírito. É o Espírito Santo que revela aos homens quem é Jesus. Porque «ninguém é capaz de dizer: "Jesus é Senhor", a não ser pela acção do Espírito Santo»  (1 Cor  12, 3). «O Espírito penetra todas as coisas, até o que há de mais profundo em Deus [...]. Ninguém conhece o que há em Deus senão o Espírito de Deus» (1 Cor 2, 10-11). Só Deus conhece inteiramente Deus. Nós cremos no Espírito Santo, porque Ele é Deus.
INSERT INTO public.catechism_official (paragraph, content) VALUES (153, 'Quando Pedro confessa que Jesus é o Cristo, o Filho do Deus vivo, Jesus declara-lhe que esta revelação não lhe veio «da carne nem do sangue, mas do seu Pai que está nos Céus»  (Mt  16, 17)  (16). A fé é um dom de Deus, uma virtude sobrenatural infundida por Ele. «Para prestar esta adesão da fé, são necessários a prévia e concomitante ajuda da graça divina e os interiores auxílios do Espírito Santo, o qual move e converte o coração para Deus, abre os olhos do entendimento, e dá "a todos a suavidade em aceitar e crer a verdade"» (17).
INSERT INTO public.catechism_official (paragraph, content) VALUES (154, 'O acto de fé só é possível pela graça e pelos auxílios interiores do Espírito Santo. Mas não é menos verdade que crer é um acto autenticamente humano. Não é contrário nem à liberdade nem à inteligência do homem confiar em Deus e aderir às verdades por Ele reveladas. Mesmo nas relações humanas, não é contrário à nossa própria dignidade acreditar no que outras pessoas nos dizem acerca de si próprias e das suas intenções, e confiar nas suas promessas (como, por exemplo, quando um homem e uma mulher se casam), para assim entrarem em mútua comunhão. Por isso, é ainda menos contrário à nossa dignidade «prestar, pela fé, submissão plena da nossa inteligência e da nossa vontade a Deus revelador» (18) e entrar assim em comunhão intima com Ele.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (155, 'Na fé, a inteligência e a vontade humanas cooperam com a graça divina: «Credere est actas intellectus assentientis veritati divinae ex imperio voluntatis, a Deo motae per gratiam» — «Crer é o acto da inteligência que presta o seu assentimento à verdade divina, por determinação da vontade, movida pela graça de Deus» (19).
INSERT INTO public.catechism_official (paragraph, content) VALUES (156, 'O motivo de crer não é o facto de as verdades reveladas aparecerem como verdadeiras e inteligíveis à luz da nossa razão natural. Nós cremos «por causa da autoridade do próprio Deus revelador, que não pode enganar-se nem enganar-nos» (20). «Contudo, para que a homenagem da nossa fé fosse conforme à razão, Deus quis que os auxílios interiores do Espírito Santo fossem acompanhados de provas exteriores da sua Revelação» (21). Assim, os milagres de Cristo e dos santos (22), as profecias, a propagação e a santidade da Igreja, a sua fecundidade e estabilidade «são sinais certos da Revelação, adaptados à inteligência de todos» (23), «motivos de credibilidade», mostrando que o assentimento da fé não é, «de modo algum, um movimento cego do espírito» (24).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (157, 'A fé é certa, mais certa que qualquer conhecimento humano, porque se funda na própria Palavra de Deus, que não pode mentir. Sem dúvida, as verdades reveladas podem parecer obscuras à razão e à experiência humanas; mas «a certeza dada pela luz divina é maior do que a dada pela luz da razão natural» (25). «Dez mil dificuldades não fazem uma só dúvida» (26).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (158, '«A fé procura compreender» (27): é inerente à fé o desejo do crente de conhecer melhor Aquele em quem acreditou, e de compreender melhor o que Ele revelou; um conhecimento mais profundo exigirá, por sua vez, uma fé maior e cada vez mais abrasada em amor. A graça da fé abre «os olhos do coração» (Ef 1, 18) para uma inteligência viva dos conteúdos da Revelação, isto é, do conjunto do desígnio de Deus e dos mistérios da fé, da íntima conexão que os Liga entre si e com Cristo, centro do mistério revelado. Ora, para «que a compreensão da Revelação seja cada vez mais profunda, o mesmo Espírito Santo aperfeiçoa sem cessar a fé, mediante os seus dons» (28). Assim, conforme o dito de Santo Agostinho, «eu creio para compreender e compreendo para crer melhor» (29).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (159, 'Fé e ciência. «Muito embora a fé esteja acima da razão, nunca pode haver verdadeiro desacordo entre ambas: o mesmo Deus, que revela os mistérios e comunica a fé, também acendeu no espírito humano a luz da razão. E Deus não pode negar-Se a Si próprio, nem a verdade pode jamais contradizer a verdade» (30). «É por isso que a busca metódica, em todos os domínios do saber, se for conduzida de modo verdadeiramente científico e segundo as normas da moral, jamais estará em oposição à fé: as realidades profanas e as da fé encontram a sua origem num só e mesmo Deus. Mais ainda: aquele que se esforça, com perseverança e humildade, por penetrar no segredo das coisas, é como que conduzido pela mão de Deus, que sustenta todos os seres e faz que eles sejam o que são, mesmo que não tenha consciência disso» (31).
INSERT INTO public.catechism_official (paragraph, content) VALUES (160, 'Para ser humana, «a resposta da fé, dada pelo homem a Deus, deve ser voluntária. Por conseguinte, ninguém deve ser constrangido a abraçara fé contra vontade. Efectivamente, o acto de fé é voluntário por sua própria natureza» (32). «E certo que Deus chama o homem a servi-Lo em espírito e verdade; mas, se é verdade que este apelo obriga o homem em consciência, isso não quer dizer que o constranja [...]. Isto foi evidente, no mais alto grau, em Jesus Cristo» (33). De facto, Cristo convidou à fé e à conversão, mas de modo nenhum constrangeu alguém. «Deu testemunho da verdade, mas não a impôs pela força aos seus contraditores. O seu Reino [...] dilata-se graças ao amor, pelo qual, levantado na cruz, Cristo atrai a Si todos os homens (34)».
INSERT INTO public.catechism_official (paragraph, content) VALUES (161, 'Para obter a salvação é necessário acreditar em Jesus Cristo e n''Aquele que O enviou para nos salvar (35). «Porque "sem a fé não é possível agradar a Deus" (Heb 11, 6) e chegar a partilhar a condição de filhos seus; ninguém jamais pode justificar-se sem ela e ninguém que não "persevere nela até ao fim" (Mt 10, 22; 24, 13) poderá alcançar a vida eterna» (36).
INSERT INTO public.catechism_official (paragraph, content) VALUES (162, 'A fé á um dom gratuito de Deus ao homem. Mas nós podemos perder este dom inestimável. Paulo adverte Timóteo a respeito dessa possibilidade: «Combate o bom combate, guardando a fé e a boa consciência; por se afastarem desse princípio é que muitos naufragaram na fé» (1 Tm 1, 18-19). Para viver, crescer e perseverar até ao fim na fé, temos de a alimentar com a Palavra de Deus; temos de pedir ao Senhor que no-la aumente (37); ela deve «agir pela caridade» (Gl 5, 6) (38), ser sustentada pela esperança (39) e permanecer enraizada na fé da Igreja.
INSERT INTO public.catechism_official (paragraph, content) VALUES (163, 'A fé faz que saboreemos, como que de antemão, a alegria e a luz da visão beatifica, termo da nossa caminhada nesta Terra. Então veremos Deus «face a face» (1 Cor 13, 12), «tal como Ele é» (1 Jo 3, 2). A fé, portanto, é já o princípio da vida eterna:
INSERT INTO public.catechism_official (paragraph, content) VALUES (165, 'É então que nos devemos voltar para as  testemunhas da fé:  Abraão, que acreditou, «esperando contra toda a esperança» (Rm 4, 18); a Virgem Maria que, na «peregrinação da fé» (41), foi até à «noite da fé» (42), comungando no sofrimento do seu Filho e na noite do seu sepulcro (43); e tantas outras testemunhas da fé: «envoltos em tamanha nuvem de testemunhas, devemos desembaraçar-nos de todo o fardo e do pecado que nos cerca, e correr com constância o risco que nos é proposto, fixando os olhos no guia da nossa fé, o qual a leva à perfeição»  (Heb  12, 1-2).
INSERT INTO public.catechism_official (paragraph, content) VALUES (166, 'A fé é um acto pessoal, uma resposta livre do homem à proposta de Deus que Se revela. Mas não é um acto isolado. Ninguém pode acreditar sozinho, tal como ninguém pode viver só. Ninguém se deu a fé a si mesmo, como ninguém a si mesmo se deu a vida. Foi de outrem que o crente recebeu a fé; a outrem a deve transmitir. O nosso amor a Jesus e aos homens impele-nos a falar aos outros da nossa fé. Cada crente é, assim, um elo na grande cadeia dos crentes. Não posso crer sem ser amparado pela fé dos outros, e pela minha fé contribuo também para amparar os outros na fé.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (167, '«Eu creio» (44): é a fé da Igreja, professada pessoalmente por cada crente, principalmente por ocasião do Baptismo. «Nós cremos» (45): é a fé da Igreja, confessada pelos bispos reunidos em Concílio ou, de modo mais geral, pela assembleia litúrgica dos crentes. «Eu creio»: é também a Igreja, nossa Mãe, que responde a Deus pela sua fé e nos ensina a dizer: «Eu creio», «Nós cremos».
INSERT INTO public.catechism_official (paragraph, content) VALUES (168, 'É, antes de mais, a Igreja que crê, e que assim suporta, nutre e sustenta a minha fé. É primeiro a Igreja que, por toda a parte, confessa o Senhor («Te per orbem terrarum sancta confitetur Ecclesia» – «A Santa Igreja anuncia por toda a terra a glória do vosso nome» – como cantamos no «Te Deum»). Com ela e nela, também nós somos atraídos e levados a confessar: «Eu creio», «Nós cremos». É da Igreja que recebemos a fé e a vida nova em Cristo, pelo Baptismo. No Ritual Romano, o ministro do Baptismo pergunta ao catecúmeno: «Que vens pedir à Igreja de Deus?» E ele responde: – «A fé». – «Para que te serve a fé?» – «Para alcançar a vida eterna» (46).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (169, 'A salvação vem só de Deus. Mas porque é através da Igreja que recebemos a vida da fé, a Igreja é nossa Mãe. «Cremos que a Igreja é como que a mãe do nosso novo nascimento, mas não cremos na Igreja como se ela fosse a autora da nossa salvação»(47). É porque é nossa Mãe, é também a educadora da nossa fé.
INSERT INTO public.catechism_official (paragraph, content) VALUES (170, 'Não acreditamos em fórmulas, mas sim nas realidades que as fórmulas exprimem e que a fé nos permite «tocar». «O acto [de fé] do crente não se detém no enunciado, mas na realidade [enunciada]» (48). No entanto, é através das fórmulas da fé que nos aproximamos dessas realidades. As fórmulas permitem-nos exprimir e transmitir a fé, celebrá-la em comunidade, assimilá-la e dela viver cada vez mais.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (171, 'A Igreja, que é «coluna e apoio da verdade» (1 Tm 3, 15), guarda fielmente a fé transmitida aos santos de uma vez por todas (49). É ela que guarda a memória das palavras de Cristo. É ela que transmite, de geração em geração, a confissão de fé dos Apóstolos. Tal como uma mãe ensina os seus filhos a falar e, dessa forma, a compreender e a comunicar, a Igreja, nossa Mãe, ensina-nos a linguagem da fé, para nos introduzir na inteligência e na vida da fé.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (172, 'Desde há séculos, através de tantas línguas, culturas, povos e nações, a Igreja não cessa de confessar a sua fé única, recebida de um só Senhor, transmitida por um só Baptismo, enraizada na convicção de que todos os homens têm apenas um só Deus e Pai (50). Santo Ireneu de Lião, testemunha desta fé, declara:') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (173, '«A Igreja, embora dispersa por todo o mundo até aos confins da Terra, tendo recebido dos Apóstolos e dos seus discípulos a fé, [...] guarda [esta pregação e esta fé] com tanto cuidado como se habitasse numa só casa; nela crê de modo idêntico, como tendo um só coração e uma só alma; prega-a e ensina-a e transmite-a com voz unânime, como se tivesse uma só boca» (51).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (174, '«Através do mundo, as línguas diferem: mas o conteúdo da Tradição é um só e o mesmo. Nem as Igrejas estabelecidas na Germania têm outra fé ou outra tradição, nem as que se estabeleceram entre os Iberos ou entre os Celtas, as do Oriente, do Egipto ou da Líbia, nem as que se fundaram no centro do mundo» (52). «A mensagem da Igreja é verídica e sólida, porque nela aparece um só e o mesmo caminho de salvação, em todo o mundo» (53).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (175, 'Esta fé, «que recebemos da Igreja, guardamo-la nós cuidadosamente, porque sem cessar, sob a acção do Espírito de Deus, tal como um depósito de grande valor encerrado num vaso excelente, ela rejuvenesce e faz rejuvenescer o próprio vaso que a contém» (54).
INSERT INTO public.catechism_official (paragraph, content) VALUES (176, 'A fé é uma adesão pessoal, do homem todo, a Deus que Se revela. Comporta uma adesão da inteligência e da vontade à Revelação que Deus fez de Si mesmo, pelas suas acções e palavras.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (177, '«Crer» tem, pois, uma dupla referência: à pessoa e à verdade; à verdade, pela confiança na pessoa que a atesta.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (178, 'Não devermos crer em mais ninguém senão em Deus, Pai, Filho e Espírito Santo.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (180, '«Crer» é um acto humano, consciente e livre, que está de acordo com a dignidade da pessoa humana.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (181, '«Crer» é um acto eclesial. A fé da Igreja precede, gera, suporta e nutre a nossa fé. A Igreja é a Mãe de todos os crentes. «Ninguém pode ter a Deus por Pai, se não tiver a Igreja por Mãe» (55).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (182, '«Nós cremos em tudo quanto está contido na Palavra de Deus, escrita ou transmitida, e que a Igreja propõe à nossa fé como divinamente revelado»  (56).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (183, 'A fé é necessária para a salvação. O próprio Senhor o afirma: «Quem acreditar e for baptizado salvar-se-á, mas quem não acreditar será condenado» (Mc 16, 16).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (184, '«A fé é um antegozo do conhecimento que nos tornará felizes na vida futura» (57).
INSERT INTO public.catechism_official (paragraph, content) VALUES (185, 'Quem diz «Creio» afirma: «dou a minha adesão àquilo em que nós cremos». A comunhão na fé tem necessidade duma linguagem comum da fé, normativa para todos e a todos unindo na mesma confissão de fé.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (186, 'Desde a origem, a Igreja apostólica exprimiu e transmitiu a sua própria fé em fórmulas breves e normativas para todos (1). Mas bem cedo a Igreja quis também recolher o essencial da sua fé em resumos orgânicos e articulados, destinados sobretudo aos candidatos ao Baptismo.
INSERT INTO public.catechism_official (paragraph, content) VALUES (187, 'A estas sínteses da fé chamamos-lhes «profissões de fé», porque resumem a fé professada pelos cristãos. Chamamos-lhes «Credo», pelo facto de elas normalmente começarem pela palavra: «Creio». Igualmente lhes chamamos «símbolos da fé».') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (188, 'A palavra grega «symbolon» significava a metade dum objecto partido (por exemplo, um selo), que se apresentava como um sinal de identificação. As duas partes eram justapostas para verificar a identidade do portador. O «símbolo da fé» é, pois, um sinal de identificação e de comunhão entre os crentes. «Symbolon» também significa resumo, colectânea ou sumário. O «símbolo da fé» é o sumário das principais verdades da fé. Por isso, serve de ponto de referência primário e fundamental da catequese.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (189, 'A primeira «profissão de fé» faz-se por ocasião do Baptismo. O «símbolo da fé» é, antes de mais nada, o símbolo baptismal. E uma vez que o Baptismo é conferido «em nome do Pai e do Filho e do Espírito Santo»(Mt 28, 19), as verdades da fé professadas por ocasião do Baptismo articulam-se segundo a sua referência às três pessoas da Santíssima Trindade.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (190, 'O Símbolo divide-se, portanto, em três partes: «na primeira, trata da Primeira Pessoa divina e da obra admirável da criação: na segunda, da Segunda Pessoa divina e do mistério da Redenção dos homens; na terceira, da Terceira Pessoa divina, fonte e princípio da nossa santificação» (3). São estes «os três capítulos do nosso selo [baptismal]» (4).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (191, 'O Símbolo «está estruturado em três partes [...] subdivididas em fórmulas variadas e muito adequadas. Segundo uma comparação frequentemente empregada pelos Padres, chamamos-lhes artigos. De facto, assim como nos nossos membros há certas articulações que os distinguem e separam, do mesmo modo, nesta profissão de fé, foi com razão e propriedade que se deu o nome de artigos às verdades que devemos crer em particular e de modo distinto» (5). Segundo uma antiga tradição, já atestada por Santo Ambrósio, é costume enumerar doze artigos do Credo, simbolizando, com o número dos doze Apóstolos, o conjunto da fé apostólica (6).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (192, 'Foram numerosas, ao longo dos séculos, e correspondendo sempre às necessidades das diferentes épocas, as profissões ou símbolos da fé: os símbolos das diferentes Igrejas apostólicas e antigas (7), o símbolo «Quicumque», chamado de Santo Atanásio (8), as profissões de fé de certos concílios (Toledo (9); Latrão (10): Lião (11) Trento (12)) ou de certos papas, como a «Fides Damasi» (13) ou o «Credo do Povo de Deus», de Paulo VI (1968) (14).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (193, 'Nenhum dos símbolos dos diferentes períodos da vida da Igreja pode ser considerado ultrapassado ou inútil. Todos nos ajudam a abraçar e a aprofundar hoje a fé de sempre, através dos diversos resumos que dela se fizeram.
INSERT INTO public.catechism_official (paragraph, content) VALUES (194, 'O Símbolo dos Apóstolos, assim chamado porque se considera, com justa razão, o resumo fiel da fé dos Apóstolos. É o antigo símbolo baptismal da Igreja de Roma. A sua grande autoridade vem-lhe deste facto: «É o símbolo adoptado pela Igreja romana, aquela em que Pedro, o primeiro dos Apóstolos, teve a sua cátedra, e para a qual ele trouxe a expressão da fé comum» (15).') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (195, 'O Símbolo dito de Niceia-Constantinopla deve a sua grande autoridade ao facto de ser proveniente desses dois primeiros concílios ecuménicos (dos anos de 325 e 381). Ainda hoje continua a ser comum a todas as grandes Igrejas do Oriente e do Ocidente.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (196, 'A exposição da fé, que vamos fazer, seguirá o Símbolo dos Apóstolos, que constitui, por assim dizer, «o mais antigo catecismo romano». Entretanto, a nossa exposição será completada por constantes referências ao Símbolo Niceno-Constantinopolitano, muitas vezes mais explícito e pormenorizado.') ON CONFLICT (paragraph) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO public.catechism_official (paragraph, content) VALUES (197, 'Como no dia do nosso Baptismo, quando toda a nossa vida foi confiada «a esta regra de doutrina» (Rm 6, 17), acolhemos o Símbolo da nossa fé que dá a vida. Recitar com fé o Credo é entrar em comunhão com Deus Pai, Filho e Espírito Santo. E é também entrar em comunhão com toda a Igreja, que nos transmite a fé e em cujo seio nós acreditamos:
